let roadClosureAsset: any = null;
try {
  roadClosureAsset = require("../../assets/road-closure.jpg");
} catch {
  roadClosureAsset = null;
}

let cctvGceAsset: any = null;
try {
  cctvGceAsset = require("../../assets/cctv-gce.png");
} catch {
  cctvGceAsset = null;
}

let potholeAsset: any = null;
try {
  potholeAsset = require("../../assets/pothole-central-park.jpg");
} catch {
  potholeAsset = null;
}

export const ROAD_CLOSURE_BASE64 = "data:image/jpeg;base64,";

export const roadClosureImage = roadClosureAsset || { uri: ROAD_CLOSURE_BASE64 };

export function getRoadClosureImageSource() {
  if (roadClosureAsset) return roadClosureAsset;
  if (typeof window !== "undefined") return { uri: "/road-closure.jpg" };
  return { uri: ROAD_CLOSURE_BASE64 };
}

export function getCctvGceImageSource() {
  if (cctvGceAsset) return cctvGceAsset;
  return { uri: "/cctv-gce.png" };
}

export function getPotholeImageSource() {
  if (potholeAsset) return potholeAsset;
  return { uri: "/pothole-central-park.jpg" };
}

export function getAnnouncementImageSource(imageUrl?: string, id?: string) {
  if (id === "ann-01" || imageUrl === "/road-closure.jpg" || imageUrl === "road-closure.jpg" || imageUrl === "assets/road-closure.jpg") {
    return getRoadClosureImageSource();
  }
  if (imageUrl === "/cctv-gce.png" || imageUrl === "assets/cctv-gce.png" || imageUrl === "cctv-gce.png") {
    return getCctvGceImageSource();
  }
  if (imageUrl === "/pothole-central-park.jpg" || imageUrl === "assets/pothole-central-park.jpg" || imageUrl === "pothole-central-park.jpg") {
    return getPotholeImageSource();
  }
  if (!imageUrl) return null;
  if (imageUrl.startsWith("http://") || imageUrl.startsWith("https://") || imageUrl.startsWith("data:")) {
    return { uri: imageUrl };
  }
  return null;
}
